-- 2026-11-03l: interests and donations history (owner's go, 3 Nov 2026; insert only, nothing altered or deleted).
-- A. 352 registered interests found in the 53 register editions from 18 Mar 2024 to 26 Oct 2026
--    ("Claude outputs/registers/registers-all-2024-03-to-2026-10.zip") but not in mp_registered_interests: top level
--    entries of members with an mps row, all removed from the register before the newest edition. Stored like the
--    earlier interests-api-edition backfill (category number, name and id; text with donor, value and dates for
--    donations and gifts), with is_current false, first_seen_date and last_seen_date the first and last edition
--    listing them, and source 'register-editions'. Not included: 2,220 entries of former MPs with no mps row (the
--    table's foreign key) and 2,363 child payment items; both are listed for the owner.
-- B. 327 Electoral Commission donations in the official CSV of 1 Nov 2026 that were missing from political_donations,
--    reported 2022 to 2026 (after the months the 1 Nov backfill read). Fetched from the Commission's search API by
--    reported day through lib/ec-donations.ts (fetchPage, mapRow), exactly as the sync stores them. Not included: 144
--    held back as possible duplicates and 60 the search API does not return; both are listed for the owner.
-- Backups: "Claude outputs/backups/2026-11-03l-mp-registered-interests-before.csv" and
-- "...-political-donations-before.csv". Undo: ...-UNDO.sql.
-- Run: psql "$DATABASE_URL" -f scripts/migrations/2026-11-03l-interests-donations-history.sql
\set ON_ERROR_STOP on
BEGIN READ WRITE;  -- explicit: the transaction pooler can hand out a connection left with a read-only default
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

CREATE TEMP TABLE before_n ON COMMIT DROP AS
  SELECT (SELECT count(*) FROM public.mp_registered_interests) AS interests, (SELECT count(*) FROM public.political_donations) AS donations;

