DO $$
DECLARE i int; d int;
BEGIN
  SELECT (SELECT count(*) FROM public.mp_registered_interests) - interests, (SELECT count(*) FROM public.political_donations) - donations INTO i, d FROM before_n;
  IF i <> 352 OR d <> 327 THEN RAISE EXCEPTION 'refused: % interests and % donations added, expected 352 and 327', i, d; END IF;
END $$;

SELECT 'interests' AS t, (SELECT interests FROM before_n) AS before, count(*) AS after FROM public.mp_registered_interests
UNION ALL SELECT 'donations', (SELECT donations FROM before_n), count(*) FROM public.political_donations;

COMMIT;
